import{_ as t,o as s,c as d,ag as a}from"./chunks/framework.gFULg22W.js";const u=JSON.parse('{"title":"Apiary Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"dev/ARCHITECTURE.md","filePath":"dev/ARCHITECTURE.md"}'),o={name:"dev/ARCHITECTURE.md"};function i(n,e,r,c,l,p){return s(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="apiary-architecture" tabindex="-1">Apiary Architecture <a class="header-anchor" href="#apiary-architecture" aria-label="Permalink to &quot;Apiary Architecture&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Apiary provides access to multiple APIs (REST/GRPC/databases) in a &quot;two pane&quot; setup (query -&gt; result), plus markdown editor/viewer and diff capabilities. Electron main process executes request plugins; the frontend is vanilla TypeScript with direct DOM APIs. Target: individual developers.</p><h2 id="directory-structure" tabindex="-1">Directory Structure <a class="header-anchor" href="#directory-structure" aria-label="Permalink to &quot;Directory Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiary/</span></span>
<span class="line"><span>├── main.ts                 # Electron main process: BrowserWindow + ipcMain.handle() wiring</span></span>
<span class="line"><span>├── preload.ts              # contextBridge: exposes window.api / window.versions to the renderer</span></span>
<span class="line"><span>├── global.d.ts             # Api interface + window.api declaration (the typed IPC contract)</span></span>
<span class="line"><span>├── main/                   # Backend (runs in the Electron main process)</span></span>
<span class="line"><span>│   ├── api.ts              # API façade: entry CRUD, emptyRequestForKind, Perform dispatch, source sub-APIs</span></span>
<span class="line"><span>│   ├── db.ts               # JSON DB (db.json): entry CRUD, response history, format migration</span></span>
<span class="line"><span>│   └── database/           # Plugin modules, one file per request kind (+ *_test.ts unit tests)</span></span>
<span class="line"><span>│       ├── http.ts, sql.ts, grpc.ts, redis.ts, jq.ts, md.ts, diff.ts</span></span>
<span class="line"><span>│       └── sql_source.ts, http_source.ts, mcp.ts</span></span>
<span class="line"><span>├── renderer/               # Frontend (vanilla TypeScript, no framework)</span></span>
<span class="line"><span>│   ├── App.ts              # Layout mount, command palette, keyboard shortcuts, panelkaFactory</span></span>
<span class="line"><span>│   ├── store.ts            # Central state (requests, layoutConfig, activeComponentID)</span></span>
<span class="line"><span>│   ├── Sidebar.ts          # Sidebar shell</span></span>
<span class="line"><span>│   ├── sidebar/            # tree.ts, contextMenu.ts, shared.ts (pure view modules)</span></span>
<span class="line"><span>│   ├── plugins/            # Frontend plugin registry: index.ts (registry), source.ts (source Item tree, virtual keys, listing facade), cache.ts (source cache engine), one &lt;kind&gt;/ dir per kind (index.ts registration + viewer.ts frame UI)</span></span>
<span class="line"><span>│   ├── layout/             # Custom layout manager (panes/stacks/tabs/splitters)</span></span>
<span class="line"><span>│   ├── components/         # Reusable N* components (CommandPalette, TableView, ViewJSON, ...)</span></span>
<span class="line"><span>│   ├── lib/                # utils.ts (signal, m), styles.ts (css/css.raw), localStorage.ts, notification.ts</span></span>
<span class="line"><span>│   ├── EditorSQL.ts        # SQL editor (shared, imported by the sql plugin&#39;s viewer)</span></span>
<span class="line"><span>│   ├── api.ts              # Typed window.api wrapper</span></span>
<span class="line"><span>│   └── e2e/                # Playwright specs</span></span>
<span class="line"><span>├── shared/                 # Code shared by main + renderer</span></span>
<span class="line"><span>│   ├── types.ts            # Kind enum, Request/Response/History types (imported as @/types.ts)</span></span>
<span class="line"><span>│   └── option.ts, result.ts, jq.ts</span></span>
<span class="line"><span>├── scripts/                # build.ts, ci.ts</span></span>
<span class="line"><span>└── docs/dev/               # Developer documentation</span></span></code></pre></div><h2 id="key-modules" tabindex="-1">Key Modules <a class="header-anchor" href="#key-modules" aria-label="Permalink to &quot;Key Modules&quot;">​</a></h2><h3 id="backend-plugin-modules-main-database" tabindex="-1">Backend: Plugin Modules (<code>main/database/</code>) <a class="header-anchor" href="#backend-plugin-modules-main-database" aria-label="Permalink to &quot;Backend: Plugin Modules (\`main/database/\`)&quot;">​</a></h3><p><strong>Contract</strong>: each plugin is a module exporting a <code>send&lt;Kind&gt;(data)</code> function plus an <code>*EmptyRequest</code> (or default) template.</p><p><code>main/api.ts</code> routes kinds:</p><ul><li><code>emptyRequestForKind(kind)</code> returns the default data used by <code>Create</code></li><li><code>Perform(id)</code> dispatches to the plugin&#39;s <code>send&lt;Kind&gt;</code>, then <code>createResponse</code> persists the exchange into the entry&#39;s response history</li><li>Source/tool kinds are exposed through dedicated sub-APIs instead of <code>Perform</code>: <code>api.GRPC</code>, <code>api.SQLSource</code>, <code>api.HTTPSource</code>, <code>api.MCP</code></li></ul><p><strong>Plugins</strong>:</p><table tabindex="0"><thead><tr><th>Kind</th><th>File</th><th>Executed by</th><th>Response history</th></tr></thead><tbody><tr><td>HTTP</td><td>http.ts</td><td><code>Perform</code> -&gt; <code>sendHTTP</code></td><td>Yes</td></tr><tr><td>SQL</td><td>sql.ts</td><td><code>Perform</code> -&gt; <code>sendSQL</code></td><td>Yes</td></tr><tr><td>GRPC</td><td>grpc.ts</td><td><code>Perform</code> -&gt; <code>sendGRPC</code></td><td>Yes</td></tr><tr><td>JQ</td><td>jq.ts</td><td><code>Perform</code> -&gt; <code>sendJQ</code></td><td>Yes</td></tr><tr><td>Redis</td><td>redis.ts</td><td><code>Perform</code> -&gt; <code>sendRedis</code></td><td>Yes</td></tr><tr><td>MD</td><td>md.ts</td><td><code>Perform</code> -&gt; <code>sendMD</code></td><td>Yes</td></tr><tr><td>DIFF</td><td>diff.ts</td><td><code>Perform</code> -&gt; <code>sendDIFF</code></td><td>Yes</td></tr><tr><td>SQLSource</td><td>sql_source.ts</td><td><code>api.SQLSource.*</code></td><td>No (on demand)</td></tr><tr><td>HTTPSource</td><td>http_source.ts</td><td><code>api.HTTPSource.*</code></td><td>No (on demand)</td></tr><tr><td>MCP</td><td>mcp.ts</td><td><code>api.MCP.*</code></td><td>No (on demand)</td></tr></tbody></table><p>Kind identifiers are defined by the <code>Kind</code> enum in <code>shared/types.ts</code>; request data shapes are members of the <code>RequestData</code> union in the same file.</p><h3 id="frontend-request-ui-modules" tabindex="-1">Frontend: Request UI Modules <a class="header-anchor" href="#frontend-request-ui-modules" aria-label="Permalink to &quot;Frontend: Request UI Modules&quot;">​</a></h3><p><strong>Files</strong>: one <code>viewer.ts</code> per kind inside <code>renderer/plugins/&lt;kind&gt;/</code> (the former <code>renderer/Request&lt;Kind&gt;.ts</code> files); kind-specific viewer components colocate in the plugin dir (e.g. <code>plugins/mcp/tool.ts</code>), shared ones stay in <code>renderer/components/</code> (<code>TableView.ts</code>, <code>EndpointViewer.ts</code>)</p><p>Each module follows the same factory interface:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  el</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HTMLElement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  show_request</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Signal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  on</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">loaded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">push_history_entry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">unmount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Pattern</strong>: These are intentionally separate files despite similar structure. They differ in:</p><ul><li>Request form rendering</li><li>Response display (table for SQL, text for HTTP, etc.)</li></ul><p>The deletion test: these are pass-throughs but that&#39;s OK - they&#39;re UI adapters, not shallow logic.</p><p><code>panelkaFactory</code> in <code>renderer/App.ts</code> dispatches kind -&gt; module via the plugin registry&#39;s <code>frame</code> hooks and is registered as the layout component factory for request panes. Source panes get their viewer components (shared ones from <code>renderer/components/</code>, kind-specific ones colocated in the plugin dir) from the plugin registry&#39;s <code>viewers</code> lists, which <code>App.ts</code> turns into layout factories.</p><h3 id="frontend-sidebar-source-items" tabindex="-1">Frontend: Sidebar + Source Items <a class="header-anchor" href="#frontend-sidebar-source-items" aria-label="Permalink to &quot;Frontend: Sidebar + Source Items&quot;">​</a></h3><ul><li><code>renderer/Sidebar.ts</code> - sidebar shell</li><li><code>renderer/sidebar/tree.ts</code> - tree rendering of request paths (persists expanded keys via <code>lib/localStorage.ts</code>); renders generic rows (root-item badge via the facade&#39;s <code>sourceBadge</code> + loading pulse for requests, baked tag/label for source items) and delegates all source data to the <code>renderer/plugins/source.ts</code> facade</li><li><code>renderer/sidebar/contextMenu.ts</code>, <code>shared.ts</code> (pure view modules; menu entries come from the plugin registry, &quot;Refresh&quot; from the facade&#39;s <code>sourceRefreshable</code>/<code>sourceRefresh</code>)</li></ul><h3 id="frontend-plugins-renderer-plugins" tabindex="-1">Frontend: Plugins (<code>renderer/plugins/</code>) <a class="header-anchor" href="#frontend-plugins-renderer-plugins" aria-label="Permalink to &quot;Frontend: Plugins (\`renderer/plugins/\`)&quot;">​</a></h3><p>Every request kind is also a frontend plugin. The registry drives everything that is &quot;data about a kind&quot; in the sidebar, context menu and command palette:</p><ul><li><code>renderer/plugins/cache.ts</code> - shared engine, no registry/store imports: <code>createSourceCache&lt;Entry&gt;({fetcher, errorTitle})</code> (flat <code>Entry[]</code> cache with a staleness window <code>STALE_AFTER</code>, a <code>changed</code> version signal, <code>fetch</code>/<code>ensureFresh</code>/<code>invalidate</code>/<code>seed</code>/<code>get</code>) plus <code>listChildren</code> (listing-thunk body: serves current entries as <code>Item</code>s, fetches fire-and-forget when stale) and <code>isStale</code></li><li><code>renderer/plugins/source.ts</code> - the source-item seam in one module, and the single one the sidebar consumes. Item side: the <code>Item</code> node type, the virtual-key codec (<code>composeVirtualKey</code>/<code>parseVirtualKey</code> with <code>:</code> escaping, so item keys like HTTP <code>GET /user/:id</code> round-trip), materialization of a root <code>Item</code> into <code>TreeOption</code>s gated by the expanded-key set (collapsed folders are never fetched; empty listings become disabled &quot;Loading...&quot;/&quot;(None)&quot; placeholders; &quot;/&quot;-containing item keys nest into virtual folder chains), and click resolution (<code>resolveIn</code>). Facade side: <code>sourceBadge(id)</code> (the kind badge, carried by the kind&#39;s root item), <code>sourceChildren(id, expanded)</code>, <code>sourceResolve(sourceID, segments)</code>, <code>sourceRefreshable</code>/<code>sourceRefresh</code>/<code>sourceIsLoading</code>, resolving the kind&#39;s <code>Plugin.root(id)</code> via the registry and store</li><li><code>renderer/plugins/index.ts</code> - explicit central registry: <code>plugins</code> array (one <code>Plugin</code> per kind) and the <code>pluginsByKind</code> map</li><li><code>renderer/plugins/&lt;kind&gt;/index.ts</code> - one module per kind: always <code>{kind, frame, root}</code> (<code>frame</code> mounts the kind&#39;s <code>viewer.ts</code> UI factory into a pane; source kinds hide the eye there and pass only <code>update</code>; <code>root(id): RootItem</code> returns the kind&#39;s invisible root carrying the kind badge — the facade renders it on sidebar request rows and the command palette; kinds with sidebar source listings give the root pure-factory <code>children</code> thunks serving items from kind-private caches (fire staleness-guarded fetches; MCP eagerly fetches both listings on row expansion, tools and prompts in two separate caches fed by one deduped IPC call), other kinds a badge-only root); optionally <code>menuEntries</code> (context-menu entries, e.g. &quot;Copy as curl&quot;) and <code>viewers</code> (<code>{componentType, factory}</code> lists for item viewer panes, deduped and titled via <code>store.openViewer</code>). The dir holds the registration plus the kind&#39;s UI: <code>viewer.ts</code> (the frame factory), optionally extra viewer components (e.g. <code>mcp/tool.ts</code>), kind-private source caches (e.g. <code>mcp/source.ts</code>) and colocated tests</li></ul><p>Adding a new kind means adding one <code>renderer/plugins/&lt;kind&gt;/</code> (an <code>index.ts</code> with the <code>Plugin</code> object plus a <code>viewer.ts</code> UI factory) and registering it in <code>renderer/plugins/index.ts</code>; no <code>switch (kind)</code> edits anywhere else.</p><h3 id="frontend-store" tabindex="-1">Frontend: Store <a class="header-anchor" href="#frontend-store" aria-label="Permalink to &quot;Frontend: Store&quot;">​</a></h3><p><strong>File</strong>: <code>renderer/store.ts</code></p><p>Handles:</p><ul><li>Request state (<code>requests</code>, <code>requests2</code>)</li><li>Layout state (<code>layoutConfig</code> (zod-validated, persisted), <code>activeComponentID</code>, tab navigation)</li></ul><p>All backend access goes through <code>renderer/api.ts</code> -&gt; <code>window.api</code>.</p><h3 id="frontend-app" tabindex="-1">Frontend: App <a class="header-anchor" href="#frontend-app" aria-label="Permalink to &quot;Frontend: App&quot;">​</a></h3><p><strong>File</strong>: <code>renderer/App.ts</code></p><p>Handles:</p><ul><li>Main layout mount</li><li>Command palette</li><li>Keyboard shortcuts</li><li>Modal dialogs (create, rename)</li><li><code>panelkaFactory</code> (kind -&gt; plugin.frame dispatch)</li></ul><h3 id="frontend-localstorage" tabindex="-1">Frontend: LocalStorage <a class="header-anchor" href="#frontend-localstorage" aria-label="Permalink to &quot;Frontend: LocalStorage&quot;">​</a></h3><p><strong>Extracted module</strong>: <code>renderer/lib/localStorage.ts</code></p><p>Provides clean interface:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">useLocalStorage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(key: string, init: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): {</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">get</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()}</span></span></code></pre></div><p>Used by the sidebar tree for persisting expanded keys and by the store.</p><h3 id="electron-ipc-main-ts-preload-ts-global-d-ts" tabindex="-1">Electron IPC (<code>main.ts</code> + <code>preload.ts</code> + <code>global.d.ts</code>) <a class="header-anchor" href="#electron-ipc-main-ts-preload-ts-global-d-ts" aria-label="Permalink to &quot;Electron IPC (\`main.ts\` + \`preload.ts\` + \`global.d.ts\`)&quot;">​</a></h3><ul><li><code>main.ts</code>: one <code>ipcMain.handle()</code> per channel - entry CRUD (<code>List</code>, <code>Get</code>, <code>Create</code>, <code>Duplicate</code>, <code>Read</code>, <code>Rename</code>, <code>Update</code>, <code>Delete</code>), <code>Perform</code>, and namespaced source channels (<code>GRPC.*</code>, <code>SQLSource.*</code>, <code>HTTPSource.*</code>, <code>MCP.*</code>)</li><li><code>preload.ts</code>: <code>contextBridge.exposeInMainWorld(&quot;api&quot;, api)</code> mirrors every channel (plus <code>versions</code>)</li><li><code>global.d.ts</code>: the <code>Api</code> interface - the single source of truth for the IPC surface</li></ul><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><p>User -&gt; renderer state (store/signals) -&gt; <code>window.api</code> (IPC invoke) -&gt; <code>main.ts</code> handler -&gt; <code>main/api.ts</code> -&gt; plugin <code>send*</code> -&gt; response -&gt; <code>createResponse</code> history in <code>db.json</code> -&gt; renderer DOM update.</p><h2 id="seams" tabindex="-1">Seams <a class="header-anchor" href="#seams" aria-label="Permalink to &quot;Seams&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Seam</th><th>What varies</th><th>Adapters</th></tr></thead><tbody><tr><td>Plugin module (<code>main/database/</code>)</td><td>Request kind</td><td>10 plugin files</td></tr><tr><td>Request UI (<code>renderer/plugins/&lt;kind&gt;/viewer.ts</code>)</td><td>Display format</td><td>10 viewer modules</td></tr><tr><td>IPC surface (<code>global.d.ts</code> <code>Api</code>)</td><td>main ↔ renderer contract</td><td><code>window.api</code> (preload)</td></tr><tr><td>Plugin registry (<code>renderer/plugins/</code>)</td><td>Kind-specific sidebar/menu metadata</td><td>10 plugin files + <code>index.ts</code> registry</td></tr></tbody></table><h2 id="testing-strategy" tabindex="-1">Testing Strategy <a class="header-anchor" href="#testing-strategy" aria-label="Permalink to &quot;Testing Strategy&quot;">​</a></h2><ul><li><strong>Backend</strong>: Unit tests per plugin (<code>main/database/*_test.ts</code>), plus <code>main/api.test.ts</code> and <code>main/db.test.ts</code> (<code>bun run test</code>)</li><li><strong>Frontend</strong>: Component tests (<code>renderer/plugins/*/viewer.test.ts</code>, <code>renderer/plugins/cache.test.ts</code>, <code>renderer/components/*</code>, <code>renderer/lib/*</code>) (<code>bun run test</code>)</li><li><strong>Integration</strong>: <code>main/integration.test.ts</code> via <code>bun run test:integration</code> (<code>INTEGRATION=1</code>)</li><li><strong>E2E</strong>: Playwright (<code>renderer/e2e/</code>) via <code>bun run test:e2e</code> (builds first)</li></ul><p>Tests cross at the interface, not past it.</p><h2 id="adding-new-plugins" tabindex="-1">Adding New Plugins <a class="header-anchor" href="#adding-new-plugins" aria-label="Permalink to &quot;Adding New Plugins&quot;">​</a></h2><ol><li><code>shared/types.ts</code>: add a <code>Kind</code> value and a <code>RequestData</code> member.</li><li><code>main/database/&lt;kind&gt;.ts</code>: implement <code>send&lt;Kind&gt;</code> + <code>*EmptyRequest</code>, add a unit test.</li><li><code>main/api.ts</code>: add a case in <code>emptyRequestForKind</code>, dispatch in <code>Perform</code> (performable kinds) or a dedicated sub-API (source kinds).</li><li><code>main.ts</code> + <code>preload.ts</code> + <code>global.d.ts</code>: expose new channels through the typed IPC surface.</li><li><code>renderer/plugins/&lt;kind&gt;/viewer.ts</code>: UI factory.</li><li><code>renderer/plugins/&lt;kind&gt;/index.ts</code>: <code>{kind, frame, root}</code> (root returns the invisible <code>RootItem</code> carrying the kind badge) plus any <code>menuEntries</code> / <code>viewers</code> hooks; register the plugin in <code>renderer/plugins/index.ts</code> (kind badge, context-menu entries, source listings, pane factories and viewer panes then come from the registry - no further <code>switch (kind)</code> edits). Source listings give the root <code>children</code> serving <code>Item</code> nodes from a kind-private <code>createSourceCache</code>; sidebar projection, virtual keys, placeholders and click resolution come from the facade (<code>renderer/plugins/source.ts</code>).</li></ol><h2 id="architecture-decisions-adrs" tabindex="-1">Architecture Decisions (ADRs) <a class="header-anchor" href="#architecture-decisions-adrs" aria-label="Permalink to &quot;Architecture Decisions (ADRs)&quot;">​</a></h2><ul><li><strong>Plugin per request type</strong>: Each request kind is a separate backend module (<code>main/database/</code>) and a separate frontend plugin directory (<code>renderer/plugins/&lt;kind&gt;/</code>, <code>index.ts</code> + <code>viewer.ts</code>). Adding a new kind touches both sides plus the typed IPC surface.</li><li><strong>All performable kinds persist response history</strong>: <code>Perform</code> calls <code>createResponse</code> for every dispatched kind (including MD and DIFF).</li><li><strong>Source kinds are queried on demand</strong>: SQLSource/HTTPSource/MCP have dedicated IPC endpoints instead of <code>Perform</code>; listings are cached client-side through a generic <code>createSourceCache</code> engine in <code>renderer/plugins/cache.ts</code>, one private cache (or two, for MCP&#39;s tools/prompts) per source kind. The sidebar never sees the caches: it consumes the <code>renderer/plugins/source.ts</code> facade over each kind&#39;s <code>root(id): Item</code> tree, materialized lazily along expanded paths.</li><li><strong>Frontend plugin registry</strong>: kind-specific sidebar/context-menu/command-palette data (badges, menu entries, source item rendering, staleness caching) lives in <code>renderer/plugins/</code> as an explicit registry instead of scattered <code>switch (kind)</code> statements.</li><li><strong>Custom layout manager</strong>: <code>renderer/layout/</code> implements panes/stacks/tabs/splitters directly instead of depending on a layout library.</li><li><strong>Typed IPC contract</strong>: the <code>Api</code> interface in <code>global.d.ts</code> is the single seam between preload and renderer.</li><li><strong>LocalStorage at seam</strong>: Extracted to <code>renderer/lib/localStorage.ts</code> for testability.</li></ul><h2 id="known-complexity" tabindex="-1">Known Complexity <a class="header-anchor" href="#known-complexity" aria-label="Permalink to &quot;Known Complexity&quot;">​</a></h2><ol><li><strong><code>main/api.ts</code> dispatch</strong>: every new kind touches <code>emptyRequestForKind</code> and <code>Perform</code> (or adds a sub-API namespace) - a deliberate, explicit switch</li><li><strong>Database migration</strong> (<code>main/db.ts</code>): v1 -&gt; current format handling is concentrated in one module</li><li><strong>10 structurally similar viewer modules</strong> (<code>renderer/plugins/&lt;kind&gt;/viewer.ts</code>) - intentional separation, not duplication to collapse</li></ol><h2 id="vocabulary" tabindex="-1">Vocabulary <a class="header-anchor" href="#vocabulary" aria-label="Permalink to &quot;Vocabulary&quot;">​</a></h2><ul><li><strong>Module</strong>: Any code with interface + implementation (function, class, file)</li><li><strong>Interface</strong>: Everything a caller must know (types, invariants, error modes)</li><li><strong>Seam</strong>: Where interface lives; where behaviour can vary</li><li><strong>Adapter</strong>: Concrete thing satisfying interface at seam</li><li><strong>Depth</strong>: Leverage at interface (lots of behavior behind small surface)</li></ul>`,58)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
